import { db } from "./db";
import { books, verses, explanations } from "@shared/schema";
import { eq, and } from "drizzle-orm";

const CORRECT_BHASHYA = {
  devanagari: `ईशा ईष्टे इति ईट् , तेन ईशा । ईशिता परमेश्वरः परमात्मा सर्वस्य । स हि सर्वमीष्टे सर्वजन्तूनामात्मा सन् प्रत्यगात्मतया । तेन स्वेन रूपेणात्मना ईशा वास्यम् आच्छादनीयम् । किम् ? इदं सर्वं यत्किं च यत्किञ्चित् जगत्यां पृथिव्यां जगत् तत्सर्वम् । स्वेनात्मना ईशेन प्रत्यगात्मतया अहमेवेदं सर्वमिति परमार्थसत्यरूपेणानृतमिदं सर्वं चराचरमाच्छादनीयं परमात्मना । यथा चन्दनागर्वादेरुदकादिसम्बन्धजक्लेदादिजमौपाधिकं दौर्गन्ध्यं तत्स्वरूपनिघर्षणेनाच्छाद्यते स्वेन पारमार्थिकेन गन्धेन, तद्वदेव हि स्वात्मन्यध्यस्तं स्वाभाविकं कर्तृत्वभोक्तृत्वादिलक्षणं जगद्द्वैतरूपं पृथिव्याम् , जगत्यामित्युपलक्षणार्थत्वात्सर्वमेव नामरूपकर्माख्यं विकारजातं परमार्थसत्यात्मभावनया त्यक्तं स्यात् । एवमीश्वरात्मभावनया युक्तस्य पुत्राद्येषणात्रयसंन्यासे एवाधिकारः, न कर्मसु । तेन त्यक्तेन त्यागेनेत्यर्थः । न हि त्यक्तो मृतः पुत्रो भृत्यो वा आत्मसम्बन्धिताभावादात्मानं पालयति । अतस्त्यागेनेत्ययमेवार्थः । भुञ्जीथाः पालयेथाः । एवं त्यक्तैषणस्त्वं मा गृधः गृधिम् आकाङ्क्षां मा कार्षीः धनविषयाम् । कस्य स्वित् कस्यचित् परस्य स्वस्य वा धनं मा काङ्क्षीरित्यर्थः । स्विदित्यनर्थको निपातः । अथवा, मा गृधः । कस्मात् ? कस्य स्विद्धनम् इत्याक्षेपार्थः । न कस्यचिद्धनमस्ति, यद्गृध्येत । आत्मैवेदं सर्वमितीश्वरभावनया सर्वं त्यक्तम् । अत आत्मन एवेदं सर्वम् , आत्मैव च सर्वम् । अतो मिथ्याविषयां गृधिं मा कार्षीरित्यर्थः ॥`,

  kannada: `ಈಶಾ ಈಷ್ಟೇ ಇತಿ ಈಟ್ , ತೇನ ಈಶಾ । ಈಶಿತಾ ಪರಮೇಶ್ವರಃ ಪರಮಾತ್ಮಾ ಸರ್ವಸ್ಯ । ಸ ಹಿ ಸರ್ವಮೀಷ್ಟೇ ಸರ್ವಜಂತೂನಾಮಾತ್ಮಾ ಸನ್ ಪ್ರತ್ಯಗಾತ್ಮತಯಾ । ತೇನ ಸ್ವೇನ ರೂಪೇಣಾತ್ಮನಾ ಈಶಾ ವಾಸ್ಯಮ್ ಆಚ್ಛಾದನೀಯಮ್ । ಕಿಮ್ ? ಇದಂ ಸರ್ವಂ ಯತ್ಕಿಂ ಚ ಯತ್ಕಿಂಚಿತ್ ಜಗತ್ಯಾಂ ಪೃಥಿವ್ಯಾಂ ಜಗತ್ ತತ್ಸರ್ವಮ್ । ಸ್ವೇನಾತ್ಮನಾ ಈಶೇನ ಪ್ರತ್ಯಗಾತ್ಮತಯಾ ಅಹಮೇವೇದಂ ಸರ್ವಮಿತಿ ಪರಮಾರ್ಥಸತ್ಯರೂಪೇಣಾನೃತಮಿದಂ ಸರ್ವಂ ಚರಾಚರಮಾಚ್ಛಾದನೀಯಂ ಪರಮಾತ್ಮನಾ । ಯಥಾ ಚಂದನಾಗರ್ವಾದೇರುದಕಾದಿಸಂಬಂಧಜಕ್ಲೇದಾದಿಜಮೌಪಾಧಿಕಂ ದೌರ್ಗಂಧ್ಯಂ ತತ್ಸ್ವರೂಪನಿಘರ್ಷಣೇನಾಚ್ಛಾದ್ಯತೇ ಸ್ವೇನ ಪಾರಮಾರ್ಥಿಕೇನ ಗಂಧೇನ, ತದ್ವದೇವ ಹಿ ಸ್ವಾತ್ಮನ್ಯಧ್ಯಸ್ತಂ ಸ್ವಾಭಾವಿಕಂ ಕರ್ತೃತ್ವಭೋಕ್ತೃತ್ವಾದಿಲಕ್ಷಣಂ ಜಗದ್ದ್ವೈತರೂಪಂ ಪೃಥಿವ್ಯಾಮ್ , ಜಗತ್ಯಾಮಿತ್ಯುಪಲಕ್ಷಣಾರ್ಥತ್ವಾತ್ಸರ್ವಮೇವ ನಾಮರೂಪಕರ್ಮಾಖ್ಯಂ ವಿಕಾರಜಾತಂ ಪರಮಾರ್ಥಸತ್ಯಾತ್ಮಭಾವನಯಾ ತ್ಯಕ್ತಂ ಸ್ಯಾತ್ । ಏವಮೀಶ್ವರಾತ್ಮಭಾವನಯಾ ಯುಕ್ತಸ್ಯ ಪುತ್ರಾದ್ಯೇಷಣಾತ್ರಯಸಂನ್ಯಾಸೇ ಏವಾಧಿಕಾರಃ, ನ ಕರ್ಮಸು । ತೇನ ತ್ಯಕ್ತೇನ ತ್ಯಾಗೇನೇತ್ಯರ್ಥಃ । ನ ಹಿ ತ್ಯಕ್ತೋ ಮೃತಃ ಪುತ್ರೋ ಭೃತ್ಯೋ ವಾ ಆತ್ಮಸಂಬಂಧಿತಾಭಾವಾದಾತ್ಮಾನಂ ಪಾಲಯತಿ । ಅತಸ್ತ್ಯಾಗೇನೇತ್ಯಯಮೇವಾರ್ಥಃ । ಭುಂಜೀಥಾಃ ಪಾಲಯೇಥಾಃ । ಏವಂ ತ್ಯಕ್ತೈಷಣಸ್ತ್ವಂ ಮಾ ಗೃಧಃ ಗೃಧಿಮ್ ಆಕಾಂಕ್ಷಾಂ ಮಾ ಕಾರ್ಷೀಃ ಧನವಿಷಯಾಮ್ । ಕಸ್ಯ ಸ್ವಿತ್ ಕಸ್ಯಚಿತ್ ಪರಸ್ಯ ಸ್ವಸ್ಯ ವಾ ಧನಂ ಮಾ ಕಾಂಕ್ಷೀರಿತ್ಯರ್ಥಃ । ಸ್ವಿದಿತ್ಯನರ್ಥಕೋ ನಿಪಾತಃ । ಅಥವಾ, ಮಾ ಗೃಧಃ । ಕಸ್ಮಾತ್ ? ಕಸ್ಯ ಸ್ವಿದ್ಧನಮ್ ಇತ್ಯಾಕ್ಷೇಪಾರ್ಥಃ । ನ ಕಸ್ಯಚಿದ್ಧನಮಸ್ತಿ, ಯದ್ಗೃಧ್ಯೇತ । ಆತ್ಮೈವೇದಂ ಸರ್ವಮಿತೀಶ್ವರಭಾವನಯಾ ಸರ್ವಂ ತ್ಯಕ್ತಮ್ । ಅತ ಆತ್ಮನ ಏವೇದಂ ಸರ್ವಮ್ , ಆತ್ಮೈವ ಚ ಸರ್ವಮ್ । ಅತೋ ಮಿಥ್ಯಾವಿಷಯಾಂ ಗೃಧಿಂ ಮಾ ಕಾರ್ಷೀರಿತ್ಯರ್ಥಃ ॥`,

  telugu: `ఈశా ఈష్టే ఇతి ఈట్ , తేన ఈశా । ఈశితా పరమేశ్వరః పరమాత్మా సర్వస్య । స హి సర్వమీష్టే సర్వజన్తూనామాత్మా సన్ ప్రత్యగాత్మతయా । తేన స్వేన రూపేణాత్మనా ఈశా వాస్యమ్ ఆచ్ఛాదనీయమ్ । కిమ్ ? ఇదం సర్వం యత్కిం చ యత్కిఞ్చిత్ జగత్యాం పృథివ్యాం జగత్ తత్సర్వమ్ । స్వేనాత్మనా ఈశేన ప్రత్యగాత్మతయా అహమేవేదం సర్వమితి పరమార్థసత్యరూపేణానృతమిదం సర్వం చరాచరమాచ్ఛాదనీయం పరమాత్మనా । యథా చన్దనాగర్వాదేరుదకాదిసమ్బన్ధజక్లేదాదిజమౌపాధికం దౌర్గన్ధ్యం తత్స్వరూపనిఘర్షణేనాచ్ఛాద్యతే స్వేన పారమార్థికేన గన్ధేన, తద్వదేవ హి స్వాత్మన్యధ్యస్తం స్వాభావికం కర్తృత్వభోక్తృత్వాదిలక్షణం జగద్ద్వైతరూపం పృథివ్యామ్ , జగత్యామిత్యుపలక్షణార్థత్వాత్సర్వమేవ నామరూపకర్మాఖ్యం వికారజాతం పరమార్థసత్యాత్మభావనయా త్యక్తం స్యాత్ । ఏవమీశ్వరాత్మభావనయా యుక్తస్య పుత్రాద్యేషణాత్రయసంన్యాసే ఏవాధికారః, న కర్మసు । తేన త్యక్తేన త్యాగేనేత్యర్థః । న హి త్యక్తో మృతః పుత్రో భృత్యో వా ఆత్మసమ్బన్ధితాభావాదాత్మానం పాలయతి । అతస్త్యాగేనేత్యయమేవార్థః । భుఞ్జీథాః పాలయేథాః । ఏవం త్యక్తైషణస్త్వం మా గృధః గృధిమ్ ఆకాఙ్క్షాం మా కార్షీః ధనవిషయామ్ । కస్య స్విత్ కస్యచిత్ పరస్య స్వస్య వా ధనం మా కాఙ్క్షీరిత్యర్థః । స్విదిత్యనర్థకో నిపాతః । అథవా, మా గృధః । కస్మాత్ ? కస్య స్విద్ధనమ్ ఇత్యాక్షేపార్థః । న కస్యచిద్ధనమస్తి, యద్గృధ్యేత । ఆత్మైవేదం సర్వమితీశ్వరభావనయా సర్వం త్యక్తమ్ । అత ఆత్మన ఏవేదం సర్వమ్ , ఆత్మైవ చ సర్వమ్ । అతో మిథ్యావిషయాం గృధిం మా కార్షీరిత్యర్థః ॥`,

  tamil: `ஈஶா ஈஷ்டே இதி ஈட் , தேந ஈஶா । ஈஶிதா பரமேஶ்வர: பரமாத்மா ஸர்வஸ்ய । ஸ ஹி ஸர்வமீஷ்டே ஸர்வஜந்தூநாமாத்மா ஸந் ப்ரத்யகா³த்மதயா । தேந ஸ்வேந ரூபேணாத்மநா ஈஶா வாஸ்யம் ஆச்சா²த³நீயம் । கிம் ? இத³ம் ஸர்வம் யத்கிம் ச யத்கிஞ்சித் ஜக³த்யாம் ப்ருதி²வ்யாம் ஜக³த் தத்ஸர்வம் । ஸ்வேநாத்மநா ஈஶேந ப்ரத்யகா³த்மதயா அஹமேவேத³ம் ஸர்வமிதி பரமார்த²ஸத்யரூபேணாந்ருதமித³ம் ஸர்வம் சராசரமாச்சா²த³நீயம் பரமாத்மநா । யதா² சந்த³நாக³ர்வாதே³ருத³காதி³ஸம்ப³ந்த⁴ஜக்லேதா³தி³ஜமௌபாதி⁴கம் தௌ³ர்க³ந்த்⁴யம் தத்ஸ்வரூபநிக⁴ர்ஷணேநாச்சா²த்³யதே ஸ்வேந பாரமார்தி²கேந க³ந்தே⁴ந, தத்³வதே³வ ஹி ஸ்வாத்மந்யத்⁴யஸ்தம் ஸ்வாபா⁴விகம் கர்த்ருத்வபோ⁴க்த்ருத்வாதி³லக்ஷணம் ஜக³த்³த்³வைதரூபம் ப்ருதி²வ்யாம் , ஜக³த்யாமித்யுபலக்ஷணார்த²த்வாத்ஸர்வமேவ நாமரூபகர்மாக்²யம் விகாரஜாதம் பரமார்த²ஸத்யாத்மபா⁴வநயா த்யக்தம் ஸ்யாத் । ஏவமீஶ்வராத்மபா⁴வநயா யுக்தஸ்ய புத்ராத்³யேஷணாத்ரயஸம்ந்யாஸே ஏவாதி⁴கார:, ந கர்மஸு । தேந த்யக்தேந த்யாகே³நேத்யர்த:² । ந ஹி த்யக்தோ ம்ருத: புத்ரோ ப்⁴ருத்யோ வா ஆத்மஸம்ப³ந்தி⁴தாபா⁴வாதா³த்மாநம் பாலயதி । அதஸ்த்யாகே³நேத்யயமேவார்த:² । பு⁴ஞ்ஜீதா:² பாலயேதா:² । ஏவம் த்யக்தைஷணஸ்த்வம் மா க்³ருத:⁴ க்³ருதி⁴ம் ஆகாங்க்ஷாம் மா கார்ஷீ: த⁴நவிஷயாம் । கஸ்ய ஸ்வித் கஸ்யசித் பரஸ்ய ஸ்வஸ்ய வா த⁴நம் மா காங்க்ஷீரித்யர்த:² । ஸ்விதி³த்யநர்த²கோ நிபாத: । அத²வா, மா க்³ருத:⁴ । கஸ்மாத் ? கஸ்ய ஸ்வித்³த⁴நம் இத்யாக்ஷேபார்த:² । ந கஸ்யசித்³த⁴நமஸ்தி, யத்³க்³ருத்⁴யேத । ஆத்மைவேத³ம் ஸர்வமிதீஶ்வரபா⁴வநயா ஸர்வம் த்யக்தம் । அத ஆத்மந ஏவேத³ம் ஸர்வம் , ஆத்மைவ ச ஸர்வம் । அதோ மித்²யாவிஷயாம் க்³ருதி⁴ம் மா கார்ஷீரித்யர்த:² ॥`
};

async function fixVerse1Bhashya() {
  console.log("Fixing verse 1 Shankaracharya bhashya content...");

  const existingBooks = await db.select().from(books).where(eq(books.slug, "isha-upanishad-bhashya"));
  if (existingBooks.length === 0) {
    console.log("Isha Upanishad book not found");
    return;
  }

  const book = existingBooks[0];
  const bookVerses = await db.select().from(verses).where(eq(verses.bookId, book.id));
  const verse1 = bookVerses.find(v => v.verseNumber === 1);

  if (!verse1) {
    console.log("Verse 1 not found");
    return;
  }

  console.log(`Found verse 1 with id: ${verse1.id}`);

  for (const [langCode, correctContent] of Object.entries(CORRECT_BHASHYA)) {
    const existing = await db.select().from(explanations).where(
      and(
        eq(explanations.verseId, verse1.id),
        eq(explanations.authorName, "Adi Shankaracharya"),
        eq(explanations.languageCode, langCode)
      )
    );

    if (existing.length > 0) {
      await db.update(explanations)
        .set({ content: correctContent })
        .where(eq(explanations.id, existing[0].id));
      console.log(`Updated ${langCode} bhashya for verse 1`);
    } else {
      console.log(`No existing ${langCode} explanation found for verse 1`);
    }
  }

  console.log("Verse 1 bhashya fix complete!");
}

fixVerse1Bhashya().then(() => process.exit(0)).catch(err => {
  console.error("Error:", err);
  process.exit(1);
});

