import express, { type Request, Response, NextFunction } from "express";
import { registerRoutes } from "./routes";
import { serveStatic } from "./static";
import { createServer } from "http";
import { seedDatabase, seedAdditionalCommentaries, updateIncompleteShankaraExplanations, seedEnglishVerseTranslations, seedSouthIndianVerseTranslations, updateVerseSectionTitles, updateIshaUpanishadHierarchy, syncAuthoritativeCommentaryData } from "./seed";
import { seedBhagavadGita, repairGitaSectionTitles } from "./seed-gita";
import { seedWordMeaningsFromFile } from "./seed-word-meanings-local";
import { seedEuropeanTranslations } from "./seed-european-translations";
import { seedGitaAllLanguages } from "./seed-gita-all-languages";
import { seedKathaUpanishad } from "./seed-katha-upanishad";
import { seedKathaAllLanguages } from "./seed-katha-all-languages";
import { setupAuth, registerAuthRoutes } from "./replit_integrations/auth";

const app = express();
const httpServer = createServer(app);

declare module "http" {
  interface IncomingMessage {
    rawBody: unknown;
  }
}

app.use(
  express.json({
    verify: (req, _res, buf) => {
      req.rawBody = buf;
    },
  }),
);

app.use(express.urlencoded({ extended: false }));

export function log(message: string, source = "express") {
  const formattedTime = new Date().toLocaleTimeString("en-US", {
    hour: "numeric",
    minute: "2-digit",
    second: "2-digit",
    hour12: true,
  });

  console.log(`${formattedTime} [${source}] ${message}`);
}

app.use((req, res, next) => {
  const start = Date.now();
  const path = req.path;
  let capturedJsonResponse: Record<string, any> | undefined = undefined;

  const originalResJson = res.json;
  res.json = function (bodyJson, ...args) {
    capturedJsonResponse = bodyJson;
    return originalResJson.apply(res, [bodyJson, ...args]);
  };

  res.on("finish", () => {
    const duration = Date.now() - start;
    if (path.startsWith("/api")) {
      let logLine = `${req.method} ${path} ${res.statusCode} in ${duration}ms`;
      if (capturedJsonResponse) {
        logLine += ` :: ${JSON.stringify(capturedJsonResponse)}`;
      }

      log(logLine);
    }
  });

  next();
});

(async () => {
  await setupAuth(app);
  registerAuthRoutes(app);
  await registerRoutes(httpServer, app);

  app.use((err: any, _req: Request, res: Response, next: NextFunction) => {
    const status = err.status || err.statusCode || 500;
    const message = err.message || "Internal Server Error";

    console.error("Internal Server Error:", err);

    if (res.headersSent) {
      return next(err);
    }

    return res.status(status).json({ message });
  });

  if (process.env.NODE_ENV === "production") {
    serveStatic(app);
  } else {
    const { setupVite } = await import("./vite");
    await setupVite(httpServer, app);
  }

  const port = parseInt(process.env.PORT || "5000", 10);
  httpServer.listen(
    {
      port,
      host: "0.0.0.0",
      reusePort: true,
    },
    () => {
      log(`serving on port ${port}`);

      runSeedOperations();
    },
  );
})();

async function runSeedOperations() {
  try {
    await seedDatabase().catch(console.error);
    await seedAdditionalCommentaries().catch(console.error);
    await updateIncompleteShankaraExplanations().catch(console.error);
    await syncAuthoritativeCommentaryData().catch(console.error);
    await seedEnglishVerseTranslations().catch(console.error);
    await seedSouthIndianVerseTranslations().catch(console.error);
    await updateVerseSectionTitles().catch(console.error);
    await updateIshaUpanishadHierarchy().catch(console.error);
    await seedBhagavadGita().catch(console.error);
    await repairGitaSectionTitles().catch(console.error);
    await seedWordMeaningsFromFile().catch(console.error);
    await seedKathaUpanishad().catch(console.error);
    log("All seed operations completed");
    seedEuropeanTranslations().catch(err => console.error("European translations error:", err));
    seedGitaAllLanguages().catch(err => console.error("Gita all languages error:", err));
    seedKathaAllLanguages().catch(err => console.error("Katha all languages error:", err));
  } catch (err) {
    console.error("Seed operations failed:", err);
  }
}

